# прямоугольник по углам: все целые точки, включая границу
def rect(x1, y1, x2, y2):
    return {(x, y) for x in range(x1, x2 + 1) for y in range(y1, y2 + 1)}

A = rect(0, 0, 30, 24)          # вверх 24, вправо 30
B = rect(10, 2, 81, 77)         # из (10, 2): вверх 75, вправо 71
print(len(A & B))

def rect(x1, y1, x2, y2):
    return {(x, y) for x in range(x1, x2 + 1) for y in range(y1, y2 + 1)}

A = rect(0, 0, 20, 10)
B = rect(5, 4, 13, 19)
print(len(A | B), len(A ^ B))         # объединение и «только в одной»

